4	//  Translated from W2jet/atree.f
5	//  Author: R.K. Ellis, July 1998.
6	//  The basic process is atreepp: amplitude for
7	//    q-(p4)+Q(-p2)+l-(-p5) --> q+(p1)+Q-(p3)+l+(p6)
8	//  All outgoing particles are right-handed, except Q(p3) which is left-handed.
9	//  All tree amplitudes divided by im wrt to BDKW paper.
10	//  Implementation of BDKW Eq.(3.10).
11	
12	#include "atree.hpp"
13	#include <W1jet.hpp>
14	#include <mxpart_mod.hpp>
15	#include <sprods_com_mod.hpp>
16	#include <complex>
17	
18	using namespace mxpart_mod;
19	using namespace sprods_com_mod;
